def valid(readers):
    if not (2 <= len(readers) <= 50):
        return False
    for r in readers:
        if not (isinstance(r, list) and len(r) == 2 and all(type(v) is int for v in r)):
            return False
        if not (1 <= r[0] <= 100 and 1 <= r[1] <= 3000):
            return False
    return len(set(r[0] for r in readers)) == len(readers)

