def valid(teams, k):
    if not (3 <= len(teams) <= 100):
        return False
    for t in teams:
        if not (isinstance(t, list) and len(t) == 3 and all(type(v) is int for v in t)):
            return False
        if not (1 <= t[0] <= 100 and 0 <= t[1] <= 100 and 0 <= t[2] <= 100):
            return False
    if len(set(t[0] for t in teams)) != len(teams):
        return False
    return type(k) is int and 1 <= k <= len(teams)
